-- Applied 20 Nov 2026 as migration warroom_server_v1_tidy_grants, after the security advisor's report.
-- The app never signs users in, so the signed-in role needs none of these; the audit trigger function is never called directly.
revoke execute on function public.warroom_sync_audit() from public, anon, authenticated;
revoke execute on function public.warroom_audit_list(int), public.warroom_device_enrol(text), public.warroom_device_revoke(uuid), public.warroom_devices(), public.warroom_enqueue(text, jsonb, text), public.warroom_job_cancel(bigint), public.warroom_jobs(int), public.warroom_lock(boolean), public.warroom_schedule_set(text, boolean, int, int), public.warroom_schedules(), public.warroom_server_status(), public.warroom_device_room(), public.warroom_gate(text) from public, authenticated;
grant execute on function public.warroom_audit_list(int), public.warroom_device_enrol(text), public.warroom_device_revoke(uuid), public.warroom_devices(), public.warroom_enqueue(text, jsonb, text), public.warroom_job_cancel(bigint), public.warroom_jobs(int), public.warroom_lock(boolean), public.warroom_schedule_set(text, boolean, int, int), public.warroom_schedules(), public.warroom_server_status(), public.warroom_device_room(), public.warroom_gate(text) to anon;
